217	  /** The sheet's due-total: everyone's due-total added up, skipping those that are n/a. */
218	  protected readonly dueTotal = computed(() =>
219	    sumAmounts(this.people().map((p) => this.dueOf(p)).filter((d): d is string => d !== null)),
220	  );
221	  /** How many claims on the sheet are overdue among those that count in the live totals. */
222	  protected readonly overdueCount = computed(() =>
223	    this.people().reduce((n, p) => n + this.overdueOf(p).length, 0),
224	  );
225	  /** The sheet's overdue-total: the due figures of the overdue claims that count, skipping those
226	   *  with no due. */
227	  protected readonly overdueTotal = computed(() =>
228	    sumAmounts(this.people().map((p) => this.overdueTotalOf(p))),
229	  );
230	  /** The id of the person whose editor is open, or null when the form adds a person. */
231	  protected readonly editing = signal<number | null>(null);
232	  /** The version of the person the open editor loaded. */
233	  private version = 0;
234	  /** Whether a submit is waiting for its answer: a second submit meanwhile is ignored. */
235	  private submitting = false;
236	  protected readonly error = signal('');
237	  /** The refusal of the last action taken on a person's row, shown on that row. */
238	  protected readonly personError = signal<{ id: number; message: string } | null>(null);
239	  /** The refusal of the last patron added on a person's row, shown on that row. */
240	  protected readonly patronError = signal<{ id: number; message: string } | null>(null);
241	  /** The people whose patron is waiting for its answer: a second press meanwhile is ignored. */
242	  private readonly naming = new Set<number>();
243	  /** The people whose statement is waiting for its answer: a second press meanwhile is ignored. */
244	  private readonly stating = new Set<number>();
245	  /** The people whose hold is waiting for its answer: a second press meanwhile is ignored. */
246	  private readonly holding = new Set<number>();
247	  /** The people whose retirement is waiting for its answer: a second press meanwhile is ignored. */
248	  private readonly retiring = new Set<number>();
249	  protected readonly form = new FormGroup({
250	    name: new FormControl('', { nonNullable: true }),
251	    grade: new FormControl<Grade>('A', { nonNullable: true }),
252	    /** The day the grade applies from; blank takes the sheet's today. */
253	    gradeFrom: new FormControl('', { nonNullable: true }),
254	  });
255	  /** Only the newest read of the sheet may show: a load overtaken by another is dropped. */
256	  private reads = 0;
257	
258	  constructor() {
259	    this.form.valueChanges.subscribe(() => this.error.set(''));
260	    effect(() => {
261	      const sheetId = this.session.sheetId();
262	      this.session.loads();
263	      this.people.set([]);
264	      this.claims.set([]);
265	      this.rates.set([]);
266	      this.periods.set([]);
267	      this.patrons.set([]);
268	      this.personError.set(null);
269	      this.patronError.set(null);
270	      this.reset();
271	      if (sheetId) void this.reload(sheetId);
272	    });
273	  }
274	
275	  protected open(p: Person): void {
276	    this.personError.set(null);
277	    this.patronError.set(null);
278	    this.editing.set(p.id);
279	    this.version = p.version;
280	    this.form.setValue({ name: p.name, grade: this.gradeOf(p), gradeFrom: '' });
281	    this.error.set('');
282	  }
283	
284	  /** Take a statement of the person, then show them and their claims as it left them. */
285	  protected async statement(p: Person): Promise<void> {
286	    if (this.stating.has(p.id)) return;
287	    this.stating.add(p.id);
288	    this.personError.set(null);
289	    this.patronError.set(null);
290	    try {
291	      const taken = await this.api.statement(p.id);
292	      this.people.update((ps) => ps.map((x) => (x.id === taken.person.id ? taken.person : x)));
293	      const byId = new Map(taken.claims.map((c) => [c.id, c]));
294	      this.claims.update((cs) => [...cs.filter((c) => !byId.has(c.id)), ...taken.claims].sort((a, b) => b.id - a.id));
295	    } catch {
296	      this.personError.set({ id: p.id, message: 'The statement could not be taken.' });
297	    } finally {
298	      this.stating.delete(p.id);
299	    }
300	  }
301	
302	  /** Name the person chosen as the person's patron. */
303	  protected async addPatron(p: Person, patronId: string): Promise<void> {
304	    if (this.naming.has(p.id)) return;
305	    this.personError.set(null);
306	    this.patronError.set(null);
307	    const id = Number(patronId);
308	    if (!patronId || id === p.id) {
309	      this.patronError.set({ id: p.id, message: 'Choose another person as patron.' });
310	      return;
311	    }
312	    if ((this.patronIds().get(p.id) ?? []).includes(id)) {
313	      this.patronError.set({ id: p.id, message: 'That person is already a patron.' });
314	      return;
315	    }
316	    this.naming.add(p.id);
317	    try {
318	      const added = await this.patronsApi.add(p.id, id);
319	      this.patrons.update((xs) => [...xs.filter((x) => x.id !== added.id), added]);
320	    } catch (e) {
321	      this.patronError.set({
322	        id: p.id,
323	        message: e instanceof HttpErrorResponse && e.status === 409 ? 'That person is already a patron.' : 'The patron could not be added.',
324	      });
325	    } finally {
326	      this.naming.delete(p.id);
327	    }
328	  }
329	
330	  /** The people a person may name as patron: everyone else on the sheet. */
331	  protected patronChoices(p: Person): Person[] {
332	    return this.people().filter((x) => x.id !== p.id);
333	  }
334	
335	  /** A person's backing: their patrons' due-totals added up, skipping those that are n/a. */
336	  protected backingOf(p: Person): string {
337	    const byId = new Map(this.people().map((x) => [x.id, x]));
338	    return sumAmounts((this.patronIds().get(p.id) ?? [])
339	      .map((id) => byId.get(id))
340	      .filter((x): x is Person => x !== undefined)
341	      .map((x) => this.dueOf(x))
342	      .filter((d): d is string => d !== null));
343	  }
344	
345	  /** Retire the person from the day given, or the sheet's today when it is left blank. */
346	  protected async retire(p: Person, from: string): Promise<void> {
347	    if (this.retiring.has(p.id)) return;
348	    this.retiring.add(p.id);
349	    this.personError.set(null);
350	    this.patronError.set(null);
351	    try {
352	      const saved = await this.api.retire(p.id, from.trim() || null);
353	      this.people.update((ps) => ps.map((x) => (x.id === saved.id ? saved : x)));
354	      if (this.editing() === saved.id) this.version = saved.version;
355	    } catch {
356	      this.personError.set({ id: p.id, message: 'The person could not be retired.' });
357	    } finally {
358	      this.retiring.delete(p.id);
359	    }
360	  }
361	
362	  /** Put the person on hold, or take them off it when they are on hold. */
363	  protected async hold(p: Person): Promise<void> {
364	    if (this.holding.has(p.id)) return;
365	    this.holding.add(p.id);
366	    this.personError.set(null);
367	    this.patronError.set(null);
368	    try {
369	      const saved = await this.api.hold(p.id, !p.held);
370	      this.people.update((ps) => ps.map((x) => (x.id === saved.id ? saved : x)));
371	      if (this.editing() === saved.id) this.version = saved.version;
372	    } catch {
373	      this.personError.set({ id: p.id, message: p.held ? 'The person could not be released.' : 'The person could not be put on hold.' });
374	    } finally {
375	      this.holding.delete(p.id);
376	    }
377	  }
378	
379	  protected cancel(): void {
380	    this.reset();
381	  }
382	
383	  protected async submit(): Promise<void> {
384	    if (this.submitting) return;
385	    this.error.set('');
386	    const { name, grade, gradeFrom } = this.form.getRawValue();
387	    if (!name.trim()) {
388	      this.error.set('Enter a name.');
389	      return;
390	    }
391	    if (!this.grades.includes(grade)) {
392	      this.error.set('Choose a grade of A, B or C.');
393	      return;
394	    }
395	    const id = this.editing();
396	    this.submitting = true;
397	    try {
398	      if (id === null) {
399	        const added = await this.api.add({ name, grade });
400	        this.people.update((ps) => [...ps, added]);
401	      } else {
402	        const saved = await this.api.edit(id, this.version, { name, grade, gradeFrom: gradeFrom.trim() || null });
403	        this.people.update((ps) => ps.map((p) => (p.id === saved.id ? saved : p)));
404	      }
405	      this.reset();
406	    } catch (e) {
407	      if (id !== null && e instanceof HttpErrorResponse && e.status === 412) {
408	        await this.showCurrent(id);
409	        this.error.set('Someone else saved this person in the meantime. The form now shows their current values.');
410	      } else if (e instanceof HttpErrorResponse && e.status === 409) {
411	        this.error.set('That name is already in use on this sheet.');
412	      } else {
413	        this.error.set(id === null ? 'The person could not be added.' : 'The person could not be saved.');
414	      }
415	    } finally {
416	      this.submitting = false;
417	    }
418	  }
419	
420	  /** Re-read the person whose save was overtaken and show them as they are now, in their row and in
421	   *  the still-open editor, which then saves over that version. */
422	  private async showCurrent(id: number): Promise<void> {
423	    const sheetId = this.session.sheetId();
424	    if (!sheetId) return;
425	    try {
426	      const current = (await this.api.list(sheetId)).find((p) => p.id === id);
427	      if (!current || this.editing() !== id) return;
428	      this.people.update((ps) => ps.map((p) => (p.id === id ? current : p)));
429	      this.version = current.version;
430	      this.form.setValue({ name: current.name, grade: this.gradeOf(current), gradeFrom: this.form.getRawValue().gradeFrom },
431	        { emitEvent: false });
432	    } catch {
433	      // the editor keeps what was typed; reopening it reads the person again
434	    }
435	  }
436	
437	  protected claimSaved(claim: Claim): void {
438	    this.claims.update((cs) =>
439	      cs.some((c) => c.id === claim.id)
440	        ? cs.map((c) => (c.id === claim.id ? claim : c))
441	        : [claim, ...cs].sort((a, b) => b.id - a.id),
442	    );
443	  }
444	
445	  protected quickAdded({ person, claim }: QuickAdded): void {
446	    this.people.update((ps) =>
447	      ps.some((p) => p.id === person.id) ? ps.map((p) => (p.id === person.id ? person : p)) : [...ps, person],
448	    );
449	    this.claimSaved(claim);
450	  }
451	
452	  protected rateSaved(rate: Rate): void {
453	    const key = (r: Rate) => r.grade + (r.from ?? '');
454	    this.rates.update((rs) =>
455	      [...rs.filter((r) => r.grade !== rate.grade || r.from !== rate.from), rate].sort((a, b) =>
456	        key(a) < key(b) ? -1 : key(a) > key(b) ? 1 : 0,
457	      ),
458	    );
459	  }
460	
461	  protected periodSaved(period: Period): void {
462	    this.periods.update((ps) => [...ps.filter((p) => p.id !== period.id), period].sort((a, b) => (a.from < b.from ? -1 : a.from > b.from ? 1 : 0)));
463	  }
464	
465	  /** A person's due-total: the sum of the due figures of their open and settled claims, leaving out
466	   *  the open ones while they are on hold. Null (n/a)
467	   *  when their grade on the sheet's today has no rate on it and no claim that counts has a figure
468	   *  (one kept by settling or a statement, or a live due at the grade in force on its date). */
469	  protected dueOf(p: Person): string | null {
470	    const counted = (this.claimsByPerson().get(p.id) ?? []).filter((c) => countsLive(c, p.held));
471	    const figures = counted.map((c) => claimDue(c, this.rates(), gradeOn(p.grades, c.date), this.floor(), this.lateness())).filter((d): d is string => d !== null);
472	    if (!this.pctOf().has(this.gradeOf(p)) && figures.length === 0) {
473	      return null;
474	    }
475	    return sumAmounts(figures);
476	  }
477	
478	  /** The grade a person shows: the one in force on the sheet's today. */
479	  protected gradeOf(p: Person): Grade {
480	    return gradeOn(p.grades, this.session.today()) ?? p.grade;
481	  }
482	
483	  /** A person's overdue claims among those that count in the live totals. */
484	  protected overdueOf(p: Person): Claim[] {
485	    return (this.claimsByPerson().get(p.id) ?? [])
486	      .filter((c) => countsLive(c, p.held) && overdue(c, this.terms(), this.session.today()));
487	  }
488	
489	  /** A person's overdue-total: the due figures of their overdue claims that count, skipping those
490	   *  with no due. */
491	  protected overdueTotalOf(p: Person): string {
492	    return sumAmounts(this.overdueOf(p).map((c) => claimDue(c, this.rates(), gradeOn(p.grades, c.date), this.floor(), this.lateness()))
493	      .filter((d): d is string => d !== null));
494	  }
495	
496	  private reset(): void {
497	    this.editing.set(null);
498	    this.form.reset({ name: '', grade: 'A', gradeFrom: '' }, { emitEvent: false });
499	    this.error.set('');
500	  }
501	
502	  private async reload(sheetId: string): Promise<void> {
503	    const read = ++this.reads;
504	    try {
505	      const [people, claims, rates, periods, settings, patrons] = await Promise.all([
506	        this.api.list(sheetId),
507	        this.claimsApi.list(sheetId),
508	        this.ratesApi.list(sheetId),
509	        this.periodsApi.list(sheetId),
510	        this.settingsApi.get(sheetId),
511	        this.patronsApi.list(sheetId),
512	      ]);
513	      if (read === this.reads) {
514	        this.rates.set(rates);
515	        this.floor.set(settings.floor);
516	        this.terms.set(settings.terms);
517	        this.latePct.set(settings.latePct);
518	        this.periods.set(periods);
519	        this.claims.set(claims);
520	        this.patrons.set(patrons);
521	        this.people.set(people);
522	      }
523	    } catch {
524	      // the list stays empty; the next load reads it again
525	    }
526	  }
527	}
